def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    if n <= 3:
        if last_opp == 'D' and (n == 1 or opp_d_streak >= 2):
            return 'D'
        return 'C'

    opp_c_count = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c_count += 1
    opp_rate = opp_c_count / float(n)

    w = n if n < 15 else 15
    recent_opp_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / float(w) if w else 1.0

    ac_t = 0
    ac_c = 0
    ad_t = 0
    ad_c = 0
    for i in range(1, n):
        if history[i - 1][0] == 'C':
            ac_t += 1
            if history[i][1] == 'C':
                ac_c += 1
        else:
            ad_t += 1
            if history[i][1] == 'C':
                ad_c += 1

    if ac_t >= 3:
        p_after_c = ac_c / float(ac_t)
    else:
        p_after_c = opp_rate if opp_rate > 0.5 else 0.6

    if ad_t >= 3:
        p_after_d = ad_c / float(ad_t)
    elif ad_t >= 1:
        p_after_d = ad_c / float(ad_t)
    else:
        p_after_d = 0.35 if opp_rate > 0.75 else 0.25

    retaliatory = (
        ac_t >= 3 and
        ad_t >= 2 and
        (p_after_c - p_after_d) > 0.28
    )

    forgiving = (
        ad_t >= 3 and
        p_after_d >= 0.75 and
        p_after_c >= 0.65 and
        recent_rate >= 0.60 and
        opp_rate >= 0.60
    )

    exploitable = forgiving

    hostile = (
        recent_rate <= 0.25 or
        opp_rate <= 0.30 or
        (ac_t >= 3 and p_after_c <= 0.50 and recent_rate <= 0.50)
    )

    if last_opp == 'D':
        if hostile and not forgiving:
            if my_d_streak >= 5 and recent_rate >= 0.25 and rng.random() < 0.10:
                return 'C'
            return 'D'

        if opp_d_streak == 1:
            if last_my == 'C':
                if n >= 92:
                    return 'D'
                if opp_rate >= 0.90 and recent_rate >= 0.85:
                    return 'C'
                if forgiving and n >= 70 and opp_rate >= 0.82:
                    return 'C'
                return 'D'
            else:
                if recent_rate >= 0.45 and opp_rate >= 0.40:
                    return 'C'
                return 'D'

        if opp_d_streak == 2:
            if n >= 92:
                return 'D'
            if last_my == 'D' and recent_rate >= 0.45:
                return 'C'
            return 'D' if last_my == 'C' else 'C'

        if last_my == 'C' and my_c_streak >= 2:
            return 'D'

        if my_d_streak >= 3 and recent_rate >= 0.35 and opp_rate >= 0.35:
            return 'C'

        return 'D'

    if hostile:
        if recent_rate > 0.40 and opp_rate > 0.30 and rng.random() < 0.12:
            return 'C'
        return 'D'

    if exploitable:
        if n >= 95:
            return 'D'
        if (
            n >= 88 and
            recent_rate >= 0.75 and
            opp_rate >= 0.70 and
            my_c_streak >= 3 and
            rng.random() < 0.20
        ):
            return 'D'
        if (
            last_my == 'D' and
            opp_c_streak >= 2 and
            n >= 60 and
            rng.random() < 0.12
        ):
            return 'D'

    if retaliatory:
        if last_my == 'D' and opp_c_streak >= 2:
            return 'C'
        return 'C'

    if my_d_streak >= 2 and opp_c_streak >= 2:
        return 'C'

    return 'C'
